                e.preventDefault();
                e.stopPropagation();

                var submenuId = toggle.getAttribute("aria-controls");
                var submenu = submenuId ? document.getElementById(submenuId) : toggle.nextElementSibling;
                var item = toggle.closest(".menu-item");

