            document.addEventListener('DOMContentLoaded', function () {
                var nav = document.getElementById('primary-nav');
                if (!nav) return;

                var topLevelItems = nav.querySelectorAll(':scope > ul.menu > li');

                function getTrigger(li) {
                    return li ? li.querySelector(':scope > a[aria-controls]') : null;
                }

                function getSubmenu(li) {
                    return li ? li.querySelector(':scope > .secondary-menu') : null;
                }

                function openItem(li) {
                    var trigger = getTrigger(li);
                    var submenu = getSubmenu(li);
                    if (!trigger || !submenu) return;

                    trigger.setAttribute('aria-expanded', 'true');
                    submenu.style.display = 'block';
                }

                function closeItem(li) {
                    var trigger = getTrigger(li);
                    var submenu = getSubmenu(li);
                    if (!trigger || !submenu) return;

                    trigger.setAttribute('aria-expanded', 'false');
                    submenu.style.display = '';
                }

                function closeAllExcept(exceptionLi) {
                    topLevelItems.forEach(function (li) {
                        if (li !== exceptionLi) closeItem(li);
                    });
                }

                topLevelItems.forEach(function (li) {
                    var trigger = getTrigger(li);
                    var submenu = getSubmenu(li);
                    if (!trigger || !submenu) return;

                    trigger.setAttribute('aria-expanded', 'false');

                    li.addEventListener('mouseenter', function () {
                        closeAllExcept(li);
                        openItem(li);
                    });

                    li.addEventListener('mouseleave', function () {
                        closeItem(li);
                    });

                    li.addEventListener('focusin', function () {
                        closeAllExcept(li);
                        openItem(li);
                    });

                    li.addEventListener('focusout', function () {
                        setTimeout(function () {
                            if (!li.contains(document.activeElement)) {
                                closeItem(li);
                            }
                        }, 0);
                    });
                });

                document.addEventListener('click', function (e) {
                    if (!nav.contains(e.target)) {
                        closeAllExcept(null);
                    }
                });

                nav.addEventListener('keydown', function (e) {
                    if (e.key === 'Escape') {
                        closeAllExcept(null);
                    }
                });
            });
         
         
            document.addEventListener('DOMContentLoaded', function () {
                var nav = document.getElementById('primary-nav');
                var toggle = document.getElementById('toggle-menu');
                if (!nav || !toggle) return;

                var mq = window.matchMedia('(max-width:991.98px)');

                function closeDrawer() {
                    nav.classList.remove('show');
                    toggle.classList.remove('open');
                    toggle.setAttribute('aria-expanded', 'false');
                    // If you use aria-expanded on parents, mirror it:
                    nav.querySelectorAll('.menu > li > a[aria-controls]')
                        .forEach(a => a.setAttribute('aria-expanded', 'false'));
                }

                // Close when any link inside the nav is clicked (mobile only)
                nav.addEventListener('click', function (e) {
                    if (!mq.matches) return;

                    if (e.target.closest('.menu-toggle')) {
                        return;
                    }

                    var a = e.target.closest('a');
                    if (a) closeDrawer();
                });

                // Close on client-side route changes (hash or history)
                window.addEventListener('hashchange', closeDrawer);
                window.addEventListener('popstate', closeDrawer);
            });


         
         
            // When the menu opens: focus moves to the first item.
            // Tab and Shift + Tab stay inside the menu(trapped).
            // Up / Down cycle through items.
            // Esc(and clicking a link) closes the menu and restores focus.
            // VoiceOver / TalkBack can’t swipe outside because #main and #footer are set inert / aria - hidden while open.
            document.addEventListener('DOMContentLoaded', function () {
                const nav = document.getElementById('primary-nav');   // drawer container
                const toggle = document.getElementById('toggle-menu');   // hamburger
                if (!nav || !toggle) return;

                const mq = window.matchMedia('(max-width:991.98px)');
                let prevFocus = null;

                //function visibleFocusable(container) {
                //    return Array.from(container.querySelectorAll('a, button, [tabindex]:not([tabindex="-1"])'))
                //        .filter(el => !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true' && el.offsetParent !== null);
                //}
                function visibleFocusable(container) {
                    return Array.from(container.querySelectorAll('a, button, [tabindex]:not([tabindex="-1"])'))
                        .filter(el => !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true' && el.offsetParent !== null);
                }
                // Include the hamburger toggle in the trapped focus order (on mobile).
                function getTrapItems() {
                    // Start with all focusable elements inside the nav
                    const items = visibleFocusable(nav);

                    // Prepend the hamburger toggle if it's visible
                    if (toggle && toggle.offsetParent !== null) {
                        items.unshift(toggle);
                    }

                    return items;
                }


                function setOutsideInert(isInert) {
                    // Remove rest of page from SR/Tab order while drawer is open
                    ['main', 'footer'].forEach(id => {
                        const el = document.getElementById(id);
                        if (!el) return;
                        if (isInert) {
                            el.setAttribute('aria-hidden', 'true');
                            // inert is widely supported now; harmless if ignored
                            try { el.inert = true; } catch (e) { }
                        } else {
                            el.removeAttribute('aria-hidden');
                            try { el.inert = false; } catch (e) { }
                        }
                    });
                }

                function openTrap() {
                    if (!mq.matches) return;                 // only trap on mobile drawer
                    prevFocus = document.activeElement;
                    setOutsideInert(true);

                    // Focus the first item in our trap list (hamburger, then nav items)
                    const items = getTrapItems();
                    if (items.length) items[0].focus();

                    document.addEventListener('keydown', onKeyDown, true);
                }


                function closeTrap() {
                    if (!mq.matches) return;
                    document.removeEventListener('keydown', onKeyDown, true);
                    setOutsideInert(false);
                    // Return focus to the hamburger for continuity
                    if (toggle) toggle.focus();
                }

                function onKeyDown(e) {
                    if (!mq.matches || !nav.classList.contains('show')) return;

                    const items = getTrapItems();
                    if (!items.length) return;

                    const first = items[0];
                    const last = items[items.length - 1];
                    const cur = document.activeElement;
                    const idx = items.indexOf(cur);

                    // Trap Tab within drawer (now includes hamburger)
                    if (e.key === 'Tab') {
                        if (e.shiftKey && cur === first) {
                            e.preventDefault();
                            last.focus();
                            return;
                        }
                        if (!e.shiftKey && cur === last) {
                            e.preventDefault();
                            first.focus();
                            return;
                        }
                    }

                    // Cyclic arrow navigation stays the same
                    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
                        e.preventDefault();
                        const next = e.key === 'ArrowDown'
                            ? (idx + 1 + items.length) % items.length
                            : (idx - 1 + items.length) % items.length;
                        items[next].focus();
                        return;
                    }

                    // Escape to close stays the same
                    if (e.key === 'Escape') {
                        e.preventDefault();
                        nav.classList.remove('show');
                        toggle.classList.remove('open');
                        toggle.setAttribute('aria-expanded', 'false');
                        closeTrap();
                        return;
                    }
                }


                // Close trap after any in-drawer link activates (SPA or full nav)
                nav.addEventListener('click', function (e) {
                    if (!mq.matches) return;

                    if (e.target.closest('.menu-toggle')) {
                        return;
                    }

                    const a = e.target.closest('a');
                    if (a) {
                        nav.classList.remove('show');
                        toggle.classList.remove('open');
                        toggle.setAttribute('aria-expanded', 'false');
                        closeTrap();
                    }
                });

                // If your hamburger’s click is handled elsewhere, we just observe the result.
                // Wait one tick so other handlers toggle .show first, then decide to trap or release.
                if (toggle) {
                    toggle.addEventListener('click', function () {
                        setTimeout(function () {
                            const open = nav.classList.contains('show');
                            toggle.setAttribute('aria-expanded', String(open));
                            if (open) openTrap(); else closeTrap();
                        }, 0);
                    });

                    // Keyboard activation for the hamburger itself (Enter/Space)
                    toggle.addEventListener('keydown', function (e) {
                        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle.click(); }
                    });
                }

                // Close trap on route changes in SPAs (hash or history navigation)
                window.addEventListener('hashchange', closeTrap);
                window.addEventListener('popstate', closeTrap);
            });
         

     
         
             
