    (function () {
        function focusLetterSection(letter) {
            if (!letter) return;

            var section = document.getElementById(letter);
            if (!section) return;

            // Prefer focusing the section's H2 (the visible letter heading)
            var focusTarget =
                document.getElementById(letter + '-heading') ||
                section.querySelector('h2, h3, [tabindex="-1"]') ||
                section;

            // Ensure focusable for programmatic focus (won't affect normal tab order)
            if (!focusTarget.hasAttribute('tabindex')) {
                focusTarget.setAttribute('tabindex', '-1');
            }

            // Scroll to the section, then focus without snapping the viewport back up
            section.scrollIntoView({ behavior: 'smooth', block: 'start' });

            window.setTimeout(function () {
                try {
                    focusTarget.focus({ preventScroll: true });
                } catch (e) {
                    focusTarget.focus();
                }
            }, 250);
        }

        function focusAlphabetMenu() {
            var menu = document.getElementById('alphabetMenu');
            if (!menu) return;

            // Prefer focusing the first enabled letter button
            var firstEnabledBtn = menu.querySelector('button[value]:not([disabled])');
            if (firstEnabledBtn) {
                firstEnabledBtn.focus();
                return;
            }

            // Fallback: make the menu focusable and focus it
            if (!menu.hasAttribute('tabindex')) {
                menu.setAttribute('tabindex', '-1');
            }
            menu.focus();
        }

        function wireAlphabetMenu() {
            var menu = document.getElementById('alphabetMenu');
            if (!menu) return;

            menu.addEventListener('click', function (e) {
                var btn = e.target.closest('button[value]');
                if (!btn) return;

                // Ignore disabled buttons
                if (btn.disabled || btn.classList.contains('disabled') || btn.getAttribute('disabled') !== null) {
                    return;
                }

                e.preventDefault();
                focusLetterSection(btn.value);
            });

            // If any custom scripts use key events on the buttons, this ensures Space/Enter behaves consistently
            menu.addEventListener('keydown', function (e) {
                var btn = e.target.closest('button[value]');
                if (!btn) return;

                if (btn.disabled || btn.classList.contains('disabled') || btn.getAttribute('disabled') !== null) {
                    return;
                }

                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    focusLetterSection(btn.value);
                }
            });
        }

