                        clearTimeout(spinnerStatusClearTimer);
                        spinnerStatusClearTimer = null;
                    }

                    statusEl.textContent = '';

                    setTimeout(function () {
                        statusEl.textContent = msg;

                        spinnerStatusClearTimer = setTimeout(function () {
                            statusEl.textContent = '';
                            spinnerStatusClearTimer = null;
                        }, 1200);
                    }, 10);
                }

