                    if (!percentEl || !panelEl) return;

                    var value = clampPercent(pct);
                    currentPercent = value;

                    percentEl.textContent = value + '%';
                    panelEl.setAttribute('aria-valuenow', String(value));

                    if (value % 10 === 0 || value === 100) {
                        announce('Loading, ' + value + ' percent complete.');
