            const ANNOUNCE_DELAY_MS = 20;
            const CLEAR_AFTER_MS = 1200;

            let clearTimer = null;

            function getStatusEl() {
                return document.getElementById(STATUS_ID);
            }

            function clearStatus() {
                const el = getStatusEl();
                if (!el) return;

                if (clearTimer) {
                    clearTimeout(clearTimer);
                    clearTimer = null;
                }

                el.textContent = "";
            }

            function announce(msg) {
                const el = getStatusEl();
                if (!el) return;

                const text = (msg || "").trim();
                if (!text) return;

                clearStatus();

                setTimeout(function () {
                    el.textContent = text;

                    clearTimer = setTimeout(function () {
                        el.textContent = "";
                        clearTimer = null;
                    }, CLEAR_AFTER_MS);
                }, ANNOUNCE_DELAY_MS);
            }

            function getCustomMessage(target) {
                if (!target || !target.getAttribute) return "";
                return target.getAttribute("data-announce") || "";
            }

            document.addEventListener("click", function (e) {
                const btn = e.target && e.target.closest ? e.target.closest(RESET_SELECTOR) : null;
                if (!btn) return;

                if (btn.disabled || btn.getAttribute("aria-disabled") === "true") return;

                const custom = getCustomMessage(btn);
                const msg = custom || DEFAULT_RESET_MSG;

                clearStatus();
                setTimeout(function () { announce(msg); }, 50);
            }, true);

            document.addEventListener("keydown", function (e) {
                if (e.key !== "Enter" && e.key !== " ") return;

                const el = e.target && e.target.closest ? e.target.closest(RESET_SELECTOR) : null;
                if (!el) return;

                const tag = (el.tagName || "").toLowerCase();
